mapper.select:
select lls.id, lls.mix_area, lls.material_name, lls.machine_code, lm.machine_name, lls.loss_rate, lls.remark, lls.del_flag, lls.create_by, lls.create_time, lls.update_by, lls.update_time from t_lhfl_lossrate_setting lls left join T_LHFL_MACHINE lm on lls.mix_area=lm.mix_area and lls.machine_code=lm.machine_code and lm.del_flag='0'
lls.del_flag = '0' and lls.mix_area = #{mixArea} and instr(lls.material_name , #{materialName})>0
and lls.machine_code = #{machineCode}
order by lls.create_time desc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers , #{data.mixArea,jdbcType= VARCHAR} mix_area,#{data.materialName,jdbcType= VARCHAR} material_name,#{data.machineCode,jdbcType= VARCHAR} machine_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_lhfl_lossrate_setting m inner join temp_table t on m.mix_area=t.mix_area and ifnull(m.material_name,'GLUE_EMPTY') = ifnull(t.material_name,'GLUE_EMPTY') and ifnull(m.machine_code,'MACHINE_EMPTY')=ifnull(t.machine_code,'MACHINE_EMPTY') and m.del_flag ='0'

mapper.insert:
insert into t_lhfl_lossrate_setting (id,mix_area,material_name,machine_code,loss_rate,remark,del_flag,create_by,create_time,update_by,update_time ) select NULL id, x.* from (
select #{lhflLossrateSetting.mixArea,jdbcType= VARCHAR} mix_area, #{lhflLossrateSetting.materialName,jdbcType= VARCHAR} material_name, #{lhflLossrateSetting.machineCode,jdbcType= VARCHAR} machine_code, #{lhflLossrateSetting.lossRate,jdbcType=DOUBLE} loss_rate, #{lhflLossrateSetting.remark,jdbcType= VARCHAR} remark, #{lhflLossrateSetting.delFlag,jdbcType= VARCHAR} del_flag, #{lhflLossrateSetting.createBy,jdbcType= VARCHAR} create_by, #{lhflLossrateSetting.createTime,jdbcType=TIMESTAMP} create_time, #{lhflLossrateSetting.updateBy,jdbcType= VARCHAR} update_by, #{lhflLossrateSetting.updateTime,jdbcType=TIMESTAMP} update_time
) x

mapper.select:
WITH temp_table AS (
SELECT #{data.mixArea,jdbcType= VARCHAR} MIX_AREA, #{data.machineName,jdbcType= VARCHAR} MACHINE_NAME,#{rowNumber} row_numbers
) select m.MACHINE_CODE machineCode from T_LHFL_MACHINE m right join temp_table t on m.MIX_AREA=t.MIX_AREA and m.MACHINE_NAME = t.MACHINE_NAME and m.del_flag ='0' order by t.row_numbers
